import java.util.*;
import java.util.function.*;
public class Batch { public static <T> List<T> run(List<T> input,Consumer<T> action){var failed=new ArrayList<T>();for(T item:input){try{action.accept(item);}catch(RuntimeException e){failed.add(item);}}return failed;} }

