import java.util.*;
import java.math.*;
public class BehaviorCheck {
  public static void main(String[] args) throws Exception {
    var seen=new ArrayList<Integer>();var failed=Batch.run(List.of(1,2,3,4),n->{if(n%2==0)throw new IllegalArgumentException();seen.add(n);});assert failed.equals(List.of(2,4));assert seen.equals(List.of(1,3));
    try{Batch.run(List.of(1),n->{throw new AssertionError("fatal");});throw new IllegalStateException();}catch(AssertionError expected){}
    System.out.println("BehaviorCheck: PASS");
  }
}

